-- A `NULL` item is `unknown`: it counts toward the two items that make the list an array and
-- takes no part in choosing the type.
-- @setup
CREATE TABLE inl (id INT, x REAL, d FLOAT8, n NUMERIC, i INT, b BIGINT, s SMALLINT);
INSERT INTO inl VALUES
  (1, 0.1, 0.1, 0.1, 1, 1, 1),
  (2, 1.5, 1.5, 1.5, 2, 2, 2),
  (3, 16777216, 9007199254740992, 16777217, 16777217, 9007199254740993, 3),
  (4, NULL, NULL, NULL, NULL, NULL, NULL);
-- @test
SELECT id, x IN (0.1, NULL) AS hit, x NOT IN (0.1, NULL) AS miss FROM inl ORDER BY id;
